// Letters with no canonical Unicode decomposition. Applied after lowercasing, so
// uppercase forms (including U+1E9E) are covered by their lowercase keys.
const TRANSLIT_MAP = Object.freeze({
  ß: 'ss',
  æ: 'ae',
  œ: 'oe',
  ø: 'o',
  đ: 'd',
  ł: 'l',
  þ: 'th',
});
const TRANSLIT_RE = new RegExp(`[${Object.keys(TRANSLIT_MAP).join('')}]`, 'g');

// Latin letters plus the combining diacritical marks block (U+0300-U+036F), so
// both precomposed and decomposed input join the same run. Scoping NFD to Latin
// runs keeps non-Latin text (Hangul, Devanagari, ...) byte-identical to before.
const LATIN_RUN_RE = /[\p{Script=Latin}̀-ͯ]+/gu;
const COMBINING_MARKS_RE = /[̀-ͯ]/g;

/**
 * Convert a string into a lowercase, dash-separated URL slug.
 * Latin diacritics are transliterated to ASCII (e.g. "Crème" -> "creme");
 * non-Latin scripts are kept as-is.
 * @param {string} str
 * @returns {string}
 */
export function slugify(str) {
  return String(str)
    .toLowerCase()
    .replace(TRANSLIT_RE, (ch) => TRANSLIT_MAP[ch])
    .replace(LATIN_RUN_RE, (run) => run.normalize('NFD').replace(COMBINING_MARKS_RE, ''))
    .trim()
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '');
}
EOF
